    }

    long long rhget(long long l, long long r) {
        return ((rh[l] - rh[r + 1] * p[r - l + 1] % MODE + MODE) % MODE + MODE) % MODE;
    }

    long long cal(long long x, long long d) {
        if (x >= d) return rhget(pos + x - d, pos + x - 1);
        long long res1 = rhget(pos, pos + x - 1);
        long long res2 = lhget(pos + x, pos + d - 1);
        return (res1 * p[d - x] % MODE + res2) % MODE;
    }

    char Getchar(long long x, long long d) {
        if (x >= d) return s[pos + x - d];
        return s[pos + d - 1];
    }

    bool check(long long x, long long y) {
        long long l = 0, r = len - pos;
        while (l < r) {
            long long mid = (l + r + 1) / 2;
            long long p = cal(x, mid);
            long long q = cal(y, mid);
            if (p == q) l = mid;
            else r = mid - 1;
        }
        l++;
        char _x = Getchar(x, l);
        char _y = Getchar(y, l);
        return _x > _y;
    }
};
```

## 典型应用

### 应用 1：位移串字典序比较

这段代码用于比较两段“位移后字符串”谁的字典序更大，核心函数是 `check`。

```cpp
bool check(long long x, long long y) {
    long long l = 0, r = len - pos;
    while (l < r) {
        long long mid = (l + r + 1) / 2;
        long long p = cal(x, mid);
        long long q = cal(y, mid);
        if (p == q) l = mid;
        else r = mid - 1;
    }
    l++;
    char _x = Getchar(x, l);
    char _y = Getchar(y, l);
    return _x > _y;
}
```

- 多个候选方案按字典序选最优（每次比较 O(log n)）
- 环形串/位移串比较大小
- 需要“最长公共前缀 + 下一个字符比较”的题

### 应用 2：位移片段哈希求值

这段代码用于求某次变换后的前缀哈希，给 `check` 的二分过程提供 O(1) 子串比较能力。

```cpp
long long cal(long long x, long long d) {
    if (x >= d) return rhget(pos + x - d, pos + x - 1);
    long long res1 = rhget(pos, pos + x - 1);
    long long res2 = lhget(pos + x, pos + d - 1);
    return (res1 * p[d - x] % MODE + res2) % MODE;
}
```

string-ac-automaton.body:
这篇对应 `AC` 结构体，用于“一个文本匹配多个模式串”。

oiwiki 参考 [AC 自动机](https://oi-wiki.org/string/ac-automaton/)

## 算法模板

```cpp
struct AC {
    int tr[N][26], tot;
    int e[N], fail[N];

    void insert(string s) {
        int u = 0;
        for (int i = 0; i < (int)s.length(); i++) {
            if (!tr[u][s[i] - 'a']) tr[u][s[i] - 'a'] = ++tot;
            u = tr[u][s[i] - 'a'];
        }
        e[u]++;
    }

    void build() {
        queue<int> q;
        for (int i = 0; i < 26; i++) if (tr[0][i]) q.push(tr[0][i]);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int i = 0; i < 26; i++) {
                if (tr[u][i]) {
                    fail[tr[u][i]] = tr[fail[u]][i];
                    q.push(tr[u][i]);
                } else {
                    tr[u][i] = tr[fail[u]][i];
                }
            }
        }
    }

    int query(string s) {
        int u = 0, res = 0;
        for (int i = 0; i < (int)s.length(); i++) {
            u = tr[u][s[i] - 'a'];
            for (int j = u; j && e[j] != -1; j = fail[j]) {
                res += e[j];
                e[j] = -1;
            }
        }
        return res;
    }
};
```

## 应用场景

### 应用 1：构建多模式匹配自动机

这段代码用于先把所有模式串插入 Trie，再通过 `build` 构建 fail 指针与自动机转移。

```cpp
void insert(string s) {
    int u = 0;
    for (int i = 0; i < (int)s.length(); i++) {
        if (!tr[u][s[i] - 'a']) tr[u][s[i] - 'a'] = ++tot;
        u = tr[u][s[i] - 'a'];
    }
    e[u]++;
}

void build() {
    queue<int> q;
    for (int i = 0; i < 26; i++) if (tr[0][i]) q.push(tr[0][i]);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int i = 0; i < 26; i++) {
            if (tr[u][i]) {
                fail[tr[u][i]] = tr[fail[u]][i];
                q.push(tr[u][i]);
            } else {
                tr[u][i] = tr[fail[u]][i];
            }
        }
    }
}
```

- 多关键字过滤
- 文本中出现了多少个模式串（可去重计数）
- 病毒串匹配、敏感词匹配

### 应用 2：文本扫描统计命中

这段代码用于在文本上跑自动机并沿 fail 链回溯统计命中次数。

```cpp
int query(string s) {
    int u = 0, res = 0;
    for (int i = 0; i < (int)s.length(); i++) {
        u = tr[u][s[i] - 'a'];
        for (int j = u; j && e[j] != -1; j = fail[j]) {
            res += e[j];
            e[j] = -1;
        }
    }
    return res;
}
```

## 使用注意

- 当前 `query` 里会把命中节点 `e[j]` 置为 `-1`，用于“每个模式最多计一次”
- 若题目要求“可重复命中”，要改统计方式（比如额外计数数组，不直接覆写 `e`）

algorithm-luogu-p1347.body:
洛谷题目链接[P1347](https://www.luogu.com.cn/problem/P1347)

## 看题

### 数据范围
        这道题给的数据范围很小，所以支持一通乱搞。

### 读题并且看样例
        发现题目给你了这些字母的对应关系，要你判断给出的关系是否能确定这些字母的顺序。很明显，有三种情况：1.能从第 x 个关系中确定关系；2.在第 x 个关系中发现矛盾点；3.给出的关系不能确定顺序。

## 分析
        要从这些关系之间找到字母顺序，顺序从小到大，要找顺序，那很容易就能想到拓扑排序，再看题目，发现这些关系可以转化为有向无环图中的关系，比如关系A<B，可以转化为图中A->B

## 拓扑排序的板子

```cpp
vector<vector<int> > adj; // 邻接表
int in[N];  // 存储每个结点的入度

bool toposort() {

	vector<int> L;
	queue<int> S;
	//预处理：把入度为0的点都放进去
	for (int i = 1; i <= n; i++)
		if (!in[i]) 
			S.push(i);

	while (!S.empty()) {
		int u = S.front(); S.pop();
		L.push_back(u);
		for (auto v : adj[u])
			if (!--in[v]) // 将当前点所有的出边的终点入度-1    如果 入度 = 0 则入队
				S.push(v);
	}

	if (L.size() == n) { // 当所有点都遍历了
		for (auto i : L) cout << i << ' ';
		return true;
	}
	else 
		return false;
}
void solve() {

	cin >> n >> m; // n个点，m条边

	adj.resize(n + 1);

	int u, v;
    for(int i = 1; i <= m; i++){
		cin >> u >> v;
		adj[u].push_back(v);
		in[v]++;
	}

	toposort();

}
```

## 处理数据

### 预处理
        入度初始化为-1的原因在处理入度那有详细解释

```cpp
adj.resize(n + 5);
memset(in, -1, sizeof in);
```

### 处理输入
        用三个字符变量分别存  字母(x) <小于符号(ch) 字母(y) （也可以用字符串读一行）

```cpp
cin >> x >> ch >> y;
u = x - 'A' + 1;
v = y - 'A' + 1;
```

### 建图
        用邻接表存，u是有向边的起点，v是有向边的终点

```cpp
adj[u].push_back(v);
```

### 处理入度
        因为是边输入关系边拓扑，有些关系的数据不能从一开始就全部输入进去，在拓扑排序的函数中（toposort()函数），会将所有入度为0的点都放进 待处理队列S 中，这样会造成存 顺序的数组L 的大小始终为n(点的个数)。但是初始化为-1，在输入这两个点的时候，再赋值为0，就可以避免这个问题。

```cpp
if (in[u] == -1) in[u] = 0;
if (in[v] == -1) in[v] = 0;
in[v]++;
```

### 拓扑函数中
        另开一个用于 记录入度的数组inn 的原因： 拓扑排序里面会减掉数组中的点的入度，会对原有入度数据造成影响，并且是多次进行拓扑排序。然后用一个数组res记录确定顺序后的字母顺序（用数字记录）。
 
## 错误思路
        一开始想的是，数据范围很小，乱搞搞也能过， 并且要判断是否成环，就将并查集查环的板子给贴上去，然后处理一下数据，判断一下第二种情况就行了。但是测完样例之后交上去，10分，把第二种情况注释掉再交，30分，我就知道不能这样搞了。

## 调整思路（但不完全）
        要判断是否成环，我将每次拓扑中访问的点的个数记录下来，再和已经有了的点的个数进行比较，如果不相等，就说明成环了。用STL中的模板set来存储目前字母（点）个数(set可以去重)，然后再每次拓扑排序中用一个计数器记录访问了的点的个数。

```cpp
//每次把起点和终点加进去
point.insert(u);
point.insert(v);
#define rep(i,a,b) for(int i = (a); i <= (b); ++i)
int toposort() {

	cnt = 0;

	vector<int>L;
	queue<int>S;

	rep(i, 1, n) 
		inn[i] = in[i];

	rep(i, 1, n) {
		if (!inn[i]) {
			S.push(i);
			cnt++; // 计数器++
		}
	}

	while (!S.empty()) {

		int u = S.front(); S.pop();

		L.push_back(u);

		for (auto v : adj[u])
			if (!--inn[v]) {
				S.push(v);
				cnt++; // 计数器++
			}
	}

	if (L.size() == n) {
		res = L;
		return 1;
	}
	if (point.size() != cnt) 
		return 2;

	return 0;
}
```

加上判断之后交上去，发现80分，看了还有某种情况没处理对。

## 再调整思路
        发现，有这样一个情况，多个点的出度都为0的时候，是不能确定顺序的，所以加上一个out数组，用于记录出度，处理方式和入度数组in一样。拓扑中每次判断出度为0的点是否唯一即可。

```cpp
int t = 0;
rep(i, 1, n)
	if (!out[i])
		t++;
```

        交上去，90，我#￥%……&。

## 再再调整思路
        发现，我忽略了自成环的情况，即关系A<A这种情况。所以改变处理输入的方式。

将输入存下来，遇到自成环的情况直接输出矛盾即可。

```cpp
rep(i, 1, m) {
	cin >> x >> ch >> y;

	if (x == y) {
		std::cout << "Inconsistency found after " << i << " relations./n";
		return;
	}

	vp[i].first = x - 'A' + 1;
	vp[i].second = y - 'A' + 1;
}
```

        交上去，AC了。

## 总结
        这是一道绿题，比较考思维，处理输入，建图，处理入度，还有成环的判断，都需要考虑完全。

